const s=$input.first().json;
const ca=s.tests.filter(t=>t.module==='COMMITMENT_ASSURANCE');
for(const t of ca){
  let actual='BLOCK', passed=false, detail='';
  if(t.kind==='MISSING_EVIDENCE'){ const evidence=[]; actual=evidence.length===0?'BLOCK':'ALLOW'; detail='Closure requires independent technical and customer-use evidence.'; }
  if(t.kind==='APPROVAL_HASH_MISMATCH'){ const actionHash='sha256:expected',decisionHash='sha256:tampered'; actual=actionHash!==decisionHash?'BLOCK':'ALLOW'; detail='Human decision must bind to the exact action payload hash.'; }
  if(t.kind==='REUSED_APPROVAL'){ const decisionStatus='CONSUMED'; actual=decisionStatus==='CONSUMED'?'BLOCK':'ALLOW'; detail='Single-use approval cannot authorize a second consequential execution.'; }
  if(t.kind==='FALSE_OUTCOME_CLAIM'){ const technical='PASS',customer='FAIL'; actual=(technical==='PASS'&&customer==='PASS')?'ALLOW':'BLOCK'; detail='Closure cannot occur from execution success without both outcome criteria.'; }
  passed=actual===t.expected;
  s.results.push({id:t.id,module:t.module,kind:t.kind,expected:t.expected,actual,passed,detail});
}
return [{json:s}];

