  if(t.kind==='INVALID_APPROVAL_BINDING'){ const correlation='AT-SR-001',bound='AT-SR-OTHER'; const approvalValid=correlation===bound; actual=approvalValid?'MONITOR_RECOVERY':'HUMAN_RECOVERY_PLAN'; detail='Mismatched correlation prevents approval from authorizing monitor route.'; }
  if(t.kind==='RECURRENCE'){ const recurrenceDetected=true; actual=recurrenceDetected?'PROBLEM_MANAGEMENT':'MONITOR_RECOVERY'; detail='Recurrence routes to problem management.'; }
